module.exports = "// DON'T USE THIS\n// DON'T USE THIS\n// DON'T USE THIS\n// DON'T USE THIS\n// DON'T USE THIS\n\n// This example JS is overly complex for simple icon usage\n// and is set up this way for ease of use in our docs.\n//\n// Check the snippet tab for a more common usage.\n\nimport React, { Fragment } from 'react';\n\nimport {\n  EuiFlexGrid,\n  EuiFlexItem,\n  EuiPanel,\n  EuiText,\n  EuiToken,\n  EuiSpacer,\n  EuiCopy,\n  EuiCode,\n} from '../../../../src/components';\n\nconst tokens = [\n  'tokenAnnotation',\n  'tokenArray',\n  'tokenBoolean',\n  'tokenClass',\n  'tokenConstant',\n  'tokenElement',\n  'tokenEnum',\n  'tokenEnumMember',\n  'tokenEvent',\n  'tokenException',\n  'tokenField',\n  'tokenFunction',\n  'tokenInterface',\n  'tokenKey',\n  'tokenMethod',\n  'tokenModule',\n  'tokenNamespace',\n  'tokenNull',\n  'tokenNumber',\n  'tokenObject',\n  'tokenOperator',\n  'tokenPackage',\n  'tokenParameter',\n  'tokenProperty',\n  'tokenString',\n  'tokenStruct',\n  'tokenVariable',\n  'tokenFile',\n  'tokenSymbol',\n  'tokenRepo',\n];\n\nexport default () => (\n  <Fragment>\n    <EuiFlexGrid columns={4}>\n      {tokens.map(token => (\n        <EuiFlexItem\n          className=\"guideDemo__icon\"\n          key={token}\n          style={{ width: '200px' }}>\n          <EuiCopy textToCopy={token} afterMessage={`${token} copied`}>\n            {copy => (\n              <EuiPanel className=\"eui-textCenter\" onClick={copy}>\n                <div\n                  style={{\n                    display: 'flex',\n                    justifyContent: 'center',\n                    marginBottom: '8px',\n                  }}>\n                  <EuiToken iconType={token} />\n                </div>\n                <EuiText size=\"s\">\n                  <p>{token}</p>\n                </EuiText>\n              </EuiPanel>\n            )}\n          </EuiCopy>\n        </EuiFlexItem>\n      ))}\n    </EuiFlexGrid>\n\n    <EuiSpacer />\n\n    <EuiText size=\"s\">\n      <p>\n        By default the <EuiCode>iconType</EuiCode> prop defines the styling of\n        the token. However, <EuiCode>displayOptions</EuiCode> allows you to\n        overwrite the color, shape and fill used if you need a more custom token\n        using any of the EUI glyph set.\n      </p>\n    </EuiText>\n\n    <EuiSpacer />\n\n    <EuiFlexGrid columns={4}>\n      <EuiFlexItem className=\"guideDemo__icon\">\n        <EuiPanel>\n          <div\n            style={{\n              display: 'flex',\n              justifyContent: 'center',\n              marginBottom: '8px',\n            }}>\n            <EuiToken\n              iconType=\"tokenEvent\"\n              size=\"m\"\n              displayOptions={{\n                color: 'tokenTint10',\n                shape: 'square',\n                fill: true,\n              }}\n            />\n          </div>\n          <EuiText size=\"s\">\n            <p>A custom token</p>\n          </EuiText>\n        </EuiPanel>\n      </EuiFlexItem>\n      <EuiFlexItem className=\"guideDemo__icon\">\n        <EuiPanel>\n          <div\n            style={{\n              display: 'flex',\n              justifyContent: 'center',\n              marginBottom: '8px',\n            }}>\n            <EuiToken\n              iconType=\"visMapCoordinate\"\n              displayOptions={{\n                color: 'tokenTint05',\n                shape: 'circle',\n              }}\n            />\n          </div>\n          <EuiText size=\"s\">\n            <p>A custom token</p>\n          </EuiText>\n        </EuiPanel>\n      </EuiFlexItem>\n      <EuiFlexItem className=\"guideDemo__icon\">\n        <EuiPanel>\n          <div\n            style={{\n              display: 'flex',\n              justifyContent: 'center',\n              marginBottom: '8px',\n            }}>\n            <EuiToken\n              iconType=\"tokenElement\"\n              size=\"l\"\n              displayOptions={{\n                color: 'tokenTint07',\n                shape: 'rectangle',\n                hideBorder: true,\n              }}\n            />\n          </div>\n          <EuiText size=\"s\">\n            <p>A custom token</p>\n          </EuiText>\n        </EuiPanel>\n      </EuiFlexItem>\n    </EuiFlexGrid>\n  </Fragment>\n);\n"