module.exports = "import React, { Fragment } from 'react';\n\nimport {\n  EuiCheckbox,\n  EuiFlexGroup,\n  EuiFlexItem,\n  EuiIconTip,\n  EuiSpacer,\n  EuiText,\n  EuiCode,\n} from '../../../../src/components';\n\nexport default () => (\n  <Fragment>\n    <EuiFlexGroup alignItems=\"center\" gutterSize=\"s\" responsive={false}>\n      <EuiFlexItem grow={false}>\n        <EuiCheckbox\n          id=\"explainedCheckbox\"\n          label=\"Use source maps\"\n          onChange={() => {}}\n        />\n      </EuiFlexItem>\n\n      <EuiFlexItem grow={false}>\n        <EuiIconTip\n          content=\"Source maps allow browser dev tools to map minified code to the original source code\"\n          position=\"right\"\n        />\n      </EuiFlexItem>\n    </EuiFlexGroup>\n\n    <EuiSpacer />\n\n    <EuiIconTip\n      aria-label=\"Warning\"\n      size=\"xl\"\n      type=\"alert\"\n      color=\"warning\"\n      content=\"I do not think it means what you think it means\"\n    />\n\n    <EuiSpacer />\n\n    <EuiText>\n      <p>\n        Pass a position utility class via <EuiCode>iconProps</EuiCode> to shift\n        for better alignment.\n        <EuiIconTip\n          type=\"iInCircle\"\n          color=\"subdued\"\n          content={\n            <span>\n              This was passed <EuiCode>.eui-alignTop</EuiCode>\n            </span>\n          }\n          iconProps={{\n            className: 'eui-alignTop',\n          }}\n        />\n      </p>\n    </EuiText>\n  </Fragment>\n);\n"