module.exports = "import React, { Component, Fragment } from 'react';\n\nimport { EuiRadio, EuiSpacer } from '../../../../src/components';\n\nimport makeId from '../../../../src/components/form/form_row/make_id';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      checked: false,\n    };\n  }\n\n  onChange = e => {\n    this.setState({\n      checked: e.target.checked,\n    });\n  };\n\n  render() {\n    return (\n      <Fragment>\n        <EuiRadio\n          id={makeId()}\n          label=\"I am a radio\"\n          checked={this.state.checked}\n          onChange={this.onChange}\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiRadio\n          id={makeId()}\n          label=\"I am a disabled radio\"\n          checked={this.state.checked}\n          onChange={this.onChange}\n          disabled\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiRadio\n          id={makeId()}\n          label=\"I am a compressed radio\"\n          checked={this.state.checked}\n          onChange={this.onChange}\n          compressed\n        />\n      </Fragment>\n    );\n  }\n}\n"